class unrotate(nn.Module):

    def __init__(self):
        super().__init__()

    def forward(self, x):
        x0, x90, x180, x270 = torch.chunk(x, 4, dim=0)
        x90 = x90.transpose(2, 3).flip(2)
        x180 = x180.flip(2).flip(3)
        x270 = x270.transpose(2, 3).flip(3)
        x = torch.cat((x0, x90, x180, x270), dim=1)
