from torch import nn
import torch.utils.data


class EntropyLoss(nn.Module):

    def __init__(self):
        super().__init__()

    def forward(self, x, eps=1e-08):
        logN = math.log(float(x.shape[0]))
        x = x * (x + eps).log() / logN
        neg_entropy = x.sum(1)
        return -neg_entropy.mean()


